package com.elpato.customer.data.repository
import com.elpato.customer.data.api.ApiService; import com.elpato.customer.data.model.BranchDto; import com.elpato.customer.domain.model.Branch; import com.elpato.customer.domain.model.DeliveryZone; import com.elpato.customer.domain.model.GeoPolygon; import com.elpato.customer.domain.model.OpeningHours; import com.elpato.customer.domain.repository.BranchRepository; import javax.inject.Inject; import javax.inject.Singleton
@Singleton class BranchRepositoryImpl @Inject constructor(private val api: ApiService) : BranchRepository {
    override suspend fun getActiveBranches(): Result<List<Branch>> = try { val r = api.getBranches(); if(r.success && r.data != null) Result.success(r.data!.map(::toDomain)) else Result.failure(Exception(r.message ?: "Error")) } catch(e: Exception) { Result.failure(e) }
    override suspend fun getBranchById(id: String): Result<Branch> = try { val r = api.getBranch(id); if(r.success && r.data != null) Result.success(toDomain(r.data!)) else Result.failure(Exception(r.message ?: "Error")) } catch(e: Exception) { Result.failure(e) }
    private fun toDomain(d: BranchDto): Branch = Branch(id = d.id, name = d.name, nameAr = d.nameAr, address = d.address, addressAr = d.addressAr, phone = d.phone, coordinates = d.coordinates, isActive = d.isActive, isOpen = d.isOpen, openingHours = d.openingHours, imageUrl = d.imageUrl, deliveryZones = d.deliveryZones.map { z -> DeliveryZone(id = z.id, branchId = z.branchId, name = z.name, nameAr = z.nameAr, polygon = GeoPolygon(z.polygon.type, z.polygon.coordinates), fee = z.fee, estimatedMinutes = z.estimatedMinutes, isActive = z.isActive, priority = z.priority) })
}
